test("empty and legacy plain/compact workspaces remain importable", () => {
  const empty={...payload(),graph:{nodes:[],edges:[],revision:0},selectedNodeIds:[],focusedNodeId:null};
  assert.deepEqual(parseWorkspaceSnapshot(encodeWorkspaceSnapshot("Empty",source,empty),source).payload,empty);
  for(const raw of [JSON.stringify(empty),encodeWorkspace(empty)]) {
    const restored=parseWorkspaceSnapshot(raw,source);
    assert.equal(restored.sameSource,false);
    assert.equal(restored.source,null);
    assert.equal(restored.payload.graph.nodes.length,0);
    assert.deepEqual(restored.payload.view,empty.view);
  }
});

test("foreign imports consistently rescope every kind of blank-node reference", () => {
  const fixed="<_:fixed>",internal=sparqlNodeId({type:"bnode",value:"internal"}),
    scoped=sparqlNodeId({type:"bnode",value:"scoped","rdf4j:scope":"old-document"});
  const edgeId=JSON.stringify([fixed,"urn:p",internal]);
  const original={...payload(),graph:{revision:1,
    nodes:[fixed,internal,scoped].map(id=>({id,label:id,kind:"blank"})),
    edges:[{id:edgeId,source:fixed,predicate:"urn:p",label:"p",target:internal}],
    statementLinks:[{id:JSON.stringify([fixed,"urn:r",scoped,"urn:q","<_:missing>"]),source:fixed,predicate:"urn:r",label:"r",
      subject:scoped,statementPredicate:"urn:q",object:"<_:missing>",statementEdgeId:JSON.stringify([scoped,"urn:q","<_:missing>"])}]},
    selectedNodeIds:[internal],focusedNodeId:scoped,namedGroups:[{id:"g",name:"G",color:"red",nodeIds:[fixed,scoped]}],
    view:{...payload().view,selectedFacetValues:[["urn:p",[fixed,internal,scoped,"<_:missing>"]]],focusedEdgeId:edgeId}};
  const raw=encodeWorkspaceSnapshot("Blank graph",source,original);
  assert.deepEqual(parseWorkspaceSnapshot(raw,source).payload,original,"same-source reload retains certified identity");
  const imported=parseWorkspaceSnapshot(raw,otherSource).payload;
  const again=parseWorkspaceSnapshot(raw,otherSource).payload;
  const ids=imported.graph.nodes.map(node=>node.id);
  assert.ok(ids.every((id,index)=>id!==original.graph.nodes[index].id));
  assert.ok(ids.every(id=>sparqlTermFromNodeId(id)?.["rdf4j:scope"]));
  assert.notEqual(ids[0],again.graph.nodes[0].id,"each import is an independent document");
  assert.equal(imported.graph.edges[0].source,ids[0]);
  assert.equal(imported.graph.edges[0].target,ids[1]);
  assert.deepEqual(imported.selectedNodeIds,[ids[1]]);
  assert.equal(imported.focusedNodeId,ids[2]);
  assert.deepEqual(imported.namedGroups[0].nodeIds,[ids[0],ids[2]]);
  assert.deepEqual(imported.view.selectedFacetValues[0][1].slice(0,3),ids);
  assert.equal(imported.graph.statementLinks[0].source,ids[0]);
  assert.equal(imported.graph.statementLinks[0].subject,ids[2]);
  assert.equal(imported.graph.statementLinks[0].object,imported.view.selectedFacetValues[0][1][3]);
  assert.equal(imported.view.focusedEdgeId,imported.graph.edges[0].id);
  assert.notEqual(imported.graph.statementLinks[0].statementEdgeId,original.graph.statementLinks[0].statementEdgeId);
});

test("portable documents never export endpoint credentials", () => {
  const original=payload();
  original.customUrl="https://user:secret@example.org/sparql?token=private";
  original.provenanceBatches=[{id:"b",label:"Load",endpoint:original.customUrl,query:"q",tripleCount:0,loadedAt:"2026-10-22T00:00:00Z",limit:null,complete:true}];
  const raw=encodeWorkspaceSnapshot("Export",source,original);
  assert.doesNotMatch(raw,/user|secret|private/);
  const parsed=parseWorkspaceSnapshot(raw,source).payload;
  assert.equal(parsed.customUrl,"");
  assert.equal(parsed.provenanceBatches[0].endpoint,"https://example.org/sparql");
  original.provenanceBatches[0].endpoint="//user:secret@example.org/sparql?token=private";
  assert.doesNotMatch(encodeWorkspaceSnapshot("Export",source,original),/user|secret|private/);
});

test("blank namespaces remain distinct for equal values from fixed, legacy, and document identities",()=>{
  const ids=["<_:same>",sparqlNodeId({type:"bnode",value:"same"}),sparqlNodeId({type:"bnode",value:"same","rdf4j:scope":"repository"})];
  const original={...payload(),graph:{revision:0,nodes:ids.map(id=>({id,label:"same",kind:"blank"})),edges:[]},selectedNodeIds:ids,focusedNodeId:null};
  const imported=parseWorkspaceSnapshot(encodeWorkspaceSnapshot("Distinct",source,original),otherSource).payload;
  assert.equal(new Set(imported.graph.nodes.map(node=>node.id)).size,3);
});

